interface ZPClientPlayer extends ZPPlayer {
    AmmoPacks?: number;
    SetAmmoPacks(this: ZPClientPlayer, value: number): void;
    GetAmmoPacks(this: ZPClientPlayer): number;
    Battery?: number;
    SetBattery(this: ZPClientPlayer, value: number): void;
    GetBattery(this: ZPClientPlayer): number;
    MaxCharge?: number;
    SetMaxBatteryCharge(this: ZPClientPlayer, value: number): void;
    GetMaxBatteryCharge(this: ZPClientPlayer): number;
    ZombieClass?: string;
    SetZombieClass(this: ZPClientPlayer, value: string): void;
    GetZombieClass(this: ZPClientPlayer): string;
    HumanClass?: string;
    SetHumanClass(this: ZPClientPlayer, value: string): void;
    GetHumanClass(this: ZPClientPlayer): string;
    Nemesis?: boolean;
    SetNemesis(this: ZPClientPlayer, value: boolean): void;
    IsNemesis(this: ZPClientPlayer): boolean | undefined;
    Survivor?: boolean;
    SetSurvivor(this: ZPClientPlayer, value: boolean): void;
    IsSurvivor(this: ZPClientPlayer): boolean | undefined;
    Footstep?: boolean;
    SetFootstep(this: ZPClientPlayer, value: boolean | undefined): void;
    GetFootstep(this: ZPClientPlayer): boolean | undefined;
    AbilityPower?: number;
    SetAbilityPower(this: ZPClientPlayer, value: number): void;
    GetAbilityPower(this: ZPClientPlayer): number;
    MaxAbilityPower?: number;
    SetMaxAbilityPower(this: ZPClientPlayer, value: number): void;
    GetMaxAbilityPower(this: ZPClientPlayer): number;
    Breath?: number;
    SetBreath(this: ZPClientPlayer, value: number): void;
    GetBreath(this: ZPClientPlayer): number;
    MaxBreath?: number;
    SetMaxBreath(this: ZPClientPlayer, value: number): void;
    GetMaxBreath(this: ZPClientPlayer): number;
    Points?: number;
    SetPoints(this: ZPClientPlayer, value: number): void;
    GetPoints(this: ZPClientPlayer): number;
    Light?: GLuaColor;
    SetLight(this: ZPClientPlayer, value: GLuaColor | undefined): void;
    GetLight(this: ZPClientPlayer): GLuaColor | undefined;
    ScreenFilter?: GLuaColor;
    SetScreenFilter(this: ZPClientPlayer, value: GLuaColor | undefined): void;
    GetScreenFilter(this: ZPClientPlayer): GLuaColor | undefined;
    GetZPClass(this: ZPClientPlayer): string;
    GetNightvisionColor(this: ZPClientPlayer): GLuaColor;
}
